function_definitions.handle_new_user():
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  INSERT INTO public.profiles (id, email, full_name, phone, role)
  VALUES (
    NEW.id,
    NEW.email,
    NEW.raw_user_meta_data->>'full_name',
    NEW.raw_user_meta_data->>'phone',
    'customer'
  );

  IF NEW.raw_user_meta_data->>'privacy_notice_acknowledged' = 'true'
     AND NEW.raw_user_meta_data->>'privacy_notice_version' = '2026-07-17' THEN
    INSERT INTO public.legal_consents (
      user_id, document_type, document_version
    ) VALUES (
      NEW.id, 'privacy_notice_acknowledged', '2026-07-17'
    ) ON CONFLICT (user_id, document_type, document_version) DO NOTHING;
  END IF;

  IF NEW.raw_user_meta_data->>'terms_of_use_accepted' = 'true'
     AND NEW.raw_user_meta_data->>'terms_of_use_version' = '2026-07-17' THEN
    INSERT INTO public.legal_consents (
      user_id, document_type, document_version
    ) VALUES (
      NEW.id, 'terms_of_use_accepted', '2026-07-17'
    ) ON CONFLICT (user_id, document_type, document_version) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$function$

function_definitions.rls_auto_enable():
CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

function_definitions.delete_product_review(uuid):
CREATE OR REPLACE FUNCTION public.delete_product_review(p_review_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  current_user_id UUID := auth.uid();
  deleted_review_id UUID;
BEGIN
  IF current_user_id IS NULL THEN
    RAISE EXCEPTION '[REVIEW_AUTH_REQUIRED] authentication required'
      USING ERRCODE = '28000';
  END IF;

  IF p_review_id IS NULL THEN
    RAISE EXCEPTION '[REVIEW_INVALID_ARGUMENT] review_id is required'
      USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.reviews AS review
  WHERE review.id = p_review_id
    AND review.user_id = current_user_id
  RETURNING review.id INTO deleted_review_id;

  RETURN jsonb_build_object(
    'review_id', p_review_id,
    'deleted', deleted_review_id IS NOT NULL
  );
END;
$function$

function_definitions.delete_current_customer_account():
CREATE OR REPLACE FUNCTION public.delete_current_customer_account()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  current_user_id UUID := auth.uid();
  v_current_role TEXT;
BEGIN
  IF current_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT profile.role
    INTO v_current_role
  FROM public.profiles AS profile
  WHERE profile.id = current_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Customer profile not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_current_role <> 'customer' THEN
    RAISE EXCEPTION 'Only customer accounts can be deleted here'
      USING ERRCODE = '42501';
  END IF;

  -- Legacy orders have a non-cascading user FK. They are not the permanent
  -- verified-purchase record and must be removed before managed auth deletion.
  DELETE FROM public.orders WHERE user_id = current_user_id;

  -- Verified transactions and shop ratings intentionally have snapshot UUIDs
  -- rather than auth.users FKs, so durable commercial proof remains.
  DELETE FROM auth.users WHERE id = current_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Authenticated customer account not found'
      USING ERRCODE = 'P0002';
  END IF;
END;
$function$

function_definitions.enforce_product_review_evidence():
CREATE OR REPLACE FUNCTION public.enforce_product_review_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.user_id IS DISTINCT FROM NEW.user_id
       OR OLD.product_id IS DISTINCT FROM NEW.product_id
       OR OLD.verified_transaction_item_id IS DISTINCT FROM
          NEW.verified_transaction_item_id
       OR OLD.is_verified_purchase IS DISTINCT FROM
          NEW.is_verified_purchase THEN
      RAISE EXCEPTION '[REVIEW_EVIDENCE_IMMUTABLE] review ownership and verification evidence cannot be changed'
        USING ERRCODE = '42501';
    END IF;

    RETURN NEW;
  END IF;

  IF NEW.verified_transaction_item_id IS NULL THEN
    RAISE EXCEPTION '[REVIEW_NOT_VERIFIED] a verified transaction item is required'
      USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.verified_transaction_items AS verified_item
    JOIN public.verified_transactions AS verified_transaction
      ON verified_transaction.id = verified_item.verified_transaction_id
    WHERE verified_item.id = NEW.verified_transaction_item_id
      AND verified_item.product_id = NEW.product_id
      AND verified_transaction.customer_user_id = NEW.user_id
  ) THEN
    RAISE EXCEPTION '[REVIEW_EVIDENCE_MISMATCH] review evidence does not match the customer and product'
      USING ERRCODE = '42501';
  END IF;

  NEW.is_verified_purchase := true;
  RETURN NEW;
END;
$function$

function_definitions.delete_customer_saved_location(uuid):
CREATE OR REPLACE FUNCTION public.delete_customer_saved_location(p_location_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  deleted_was_default BOOLEAN;
BEGIN
  DELETE FROM public.customer_saved_locations
  WHERE id = p_location_id AND user_id = auth.uid()
  RETURNING is_default INTO deleted_was_default;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF deleted_was_default THEN
    UPDATE public.customer_saved_locations
    SET is_default = true
    WHERE id = (
      SELECT id
      FROM public.customer_saved_locations
      WHERE user_id = auth.uid()
      ORDER BY created_at DESC
      LIMIT 1
    );
  END IF;

  RETURN true;
END;
$function$

