function_definitions.taxonomy_set_preview_v2(boolean,text):
CREATE OR REPLACE FUNCTION public.taxonomy_set_preview_v2(p_enabled boolean, p_taxonomy_version text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  updated_state BOOLEAN;
BEGIN
  IF p_enabled IS NULL THEN RAISE EXCEPTION 'W38_PREVIEW_VALUE_REQUIRED'; END IF;
  IF p_taxonomy_version <> 'canonical-v1.0.0' THEN
    RAISE EXCEPTION 'W38_TAXONOMY_VERSION_MISMATCH';
  END IF;
  UPDATE public.taxonomy_contract_config
  SET preview_enabled = p_enabled, updated_at = now()
  WHERE singleton_id = 1
    AND taxonomy_data_version = p_taxonomy_version
    AND preview_supported = true
  RETURNING preview_enabled INTO updated_state;
  IF NOT FOUND THEN RAISE EXCEPTION 'W38_CAPABILITY_CONFIG_INVALID'; END IF;
  RETURN updated_state;
END
$function$

function_definitions.validate_taxonomy_category_hierarchy():
CREATE OR REPLACE FUNCTION public.validate_taxonomy_category_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE parent_level SMALLINT; cycle_found BOOLEAN;
BEGIN
  IF NEW.level IS NULL THEN RETURN NEW; END IF;
  IF NEW.level=1 THEN
    IF NEW.parent_id IS NOT NULL THEN RAISE EXCEPTION 'L1 taxonomy category cannot have a parent'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.parent_id IS NULL THEN RAISE EXCEPTION 'L2-L4 taxonomy category requires a parent'; END IF;
  IF NEW.parent_id=NEW.id THEN RAISE EXCEPTION 'taxonomy category cannot parent itself'; END IF;
  SELECT level INTO parent_level FROM public.categories WHERE id=NEW.parent_id;
  IF NOT FOUND OR parent_level IS NULL OR parent_level<>NEW.level-1 THEN
    RAISE EXCEPTION 'taxonomy parent level mismatch';
  END IF;
  WITH RECURSIVE ancestors(id,parent_id) AS (
    SELECT id,parent_id FROM public.categories WHERE id=NEW.parent_id
    UNION ALL
    SELECT c.id,c.parent_id FROM public.categories c JOIN ancestors a ON c.id=a.parent_id
  ) SELECT EXISTS(SELECT 1 FROM ancestors WHERE id=NEW.id) INTO cycle_found;
  IF cycle_found THEN RAISE EXCEPTION 'taxonomy category cycle detected'; END IF;
  RETURN NEW;
END
$function$

