CREATE OR REPLACE FUNCTION public.prevent_profile_role_client_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.role() = 'authenticated' THEN
    IF TG_OP = 'INSERT'
       AND coalesce(NEW.role, 'customer') <> 'customer' THEN
      RAISE EXCEPTION
        'Setting a privileged profile role from the client is not allowed'
        USING ERRCODE = '42501';
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.role IS DISTINCT FROM NEW.role THEN
      RAISE EXCEPTION
        'Changing a profile role from the client is not allowed'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

function_definitions.cancel_active_qr_after_cart_item_change(:
CREATE OR REPLACE FUNCTION public.cancel_active_qr_after_cart_item_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'auth'
AS $function$
DECLARE
  old_cart_id UUID;
  new_cart_id UUID;
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.cart_id IS NOT DISTINCT FROM NEW.cart_id
     AND OLD.shop_product_id IS NOT DISTINCT FROM NEW.shop_product_id
     AND OLD.quantity IS NOT DISTINCT FROM NEW.quantity THEN
    RETURN NEW;
  END IF;

  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    old_cart_id := OLD.cart_id;
  END IF;

  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    new_cart_id := NEW.cart_id;
  END IF;

  PERFORM cart_row.id
  FROM public.carts AS cart_row
  WHERE cart_row.id = ANY (
    array_remove(ARRAY[old_cart_id, new_cart_id]::UUID[], NULL)
  )
  ORDER BY cart_row.id
  FOR UPDATE;

  IF EXISTS (
    SELECT 1 FROM public.carts AS cart_row
    WHERE cart_row.id = ANY (
      array_remove(ARRAY[old_cart_id, new_cart_id]::UUID[], NULL)
    )
      AND cart_row.status <> 'active'
  ) THEN
    RAISE EXCEPTION 'Cart is no longer active'
      USING ERRCODE = '55000';
  END IF;

  UPDATE public.qr_sessions AS session_row
  SET status = 'cancelled'
  WHERE session_row.status = 'active'
    AND session_row.cart_id = ANY (
      array_remove(ARRAY[old_cart_id, new_cart_id]::UUID[], NULL)
    );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

