CREATE OR REPLACE FUNCTION public.set_default_customer_saved_location(p_location_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.customer_saved_locations
    WHERE id = p_location_id AND user_id = auth.uid()
  ) THEN
